bool SelfServiceRegistrations::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("first_name"))
    {
        if(!validJsonOfField(1, "first_name", pJson["first_name"], err, true))
            return false;
    }
    else
    {
        err="The first_name column cannot be null";
        return false;
    }
    if(pJson.isMember("last_name"))
    {
        if(!validJsonOfField(2, "last_name", pJson["last_name"], err, true))
            return false;
    }
    else
    {
        err="The last_name column cannot be null";
        return false;
    }
    if(pJson.isMember("mobile_no"))
    {
        if(!validJsonOfField(3, "mobile_no", pJson["mobile_no"], err, true))
            return false;
    }
    else
    {
        err="The mobile_no column cannot be null";
        return false;
    }
    if(pJson.isMember("account_number"))
    {
        if(!validJsonOfField(4, "account_number", pJson["account_number"], err, true))
            return false;
    }
    if(pJson.isMember("authentication_mode"))
    {
        if(!validJsonOfField(5, "authentication_mode", pJson["authentication_mode"], err, true))
            return false;
    }
    if(pJson.isMember("status"))
    {
        if(!validJsonOfField(6, "status", pJson["status"], err, true))
            return false;
    }
    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(7, "created_at", pJson["created_at"], err, true))
            return false;
    }
    return true;
}
